// RSS Feed URLs from environment or hardcoded
const feeds = [
  'https://techcrunch.com/category/artificial-intelligence/feed/',
  'https://feeds.arstechnica.com/arstechnica/technology-lab',
  'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml'
];

return feeds.map(url => ({ json: { feedUrl: url } }));

// Normalize RSS items into consistent article records
const SOURCE_MAP = {
  'techcrunch.com': 'TechCrunch',
  'arstechnica.com': 'Ars Technica',
  'theverge.com': 'The Verge'
};

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const feedUrl = data.feedUrl || '';

  // Determine source name
  let source = 'Unknown';
  for (const [domain, name] of Object.entries(SOURCE_MAP)) {
    if ((data.link || feedUrl).includes(domain)) {
      source = name;
      break;
    }
  }

  // Extract category
  const category = (data.categories && data.categories[0]) 
    ? (typeof data.categories[0] === 'string' ? data.categories[0] : 'ai')
    : 'ai';

  // Clean content (strip HTML)
  const content = (data['content:encoded'] || data.content || data.contentSnippet || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const summary = (data.contentSnippet || data.summary || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 500);

  results.push({
    json: {
      title: (data.title || 'Untitled').trim(),
      url: (data.link || data.guid || '').trim(),
      source,
      published_at: data.isoDate || data.pubDate || new Date().toISOString(),
      category: category.toLowerCase(),
      summary: summary || null,
      content: content || null
    }
  });
}

return results;

// Count results
const items = $input.all();
const inserted = items.filter(i => i.json.id).length;
const total = items.length;

return [{
  json: {
    message: `Ingestion complete: ${inserted} new articles inserted out of ${total} processed.`,
    inserted,
    total,
    timestamp: new Date().toISOString()
  }
}];
